mule:set-variable.mule:value:
#[output application/java
                        ---
                        // Defensive: if error is null or fatally broken,
                        // build a minimal safe error object so the rest of
                        // the flow never encounters a null.
                        if ( vars.error != null
                             and (vars.error.errorType != null or vars.error.description != null)
                           )
                            vars.error
                        else
                            {
                                errorType: {
                                    namespace: "MULE",
                                    identifier: "UNKNOWN"
                                },
                                description: (vars.error default {}).description
                                    default "An unexpected error occurred",
                                childErrors: (vars.error default {}).childErrors default [],
                                suppressedErrors: (vars.error default {}).suppressedErrors default []
                            }

#[output application/java
                        import getErrorTypeAsString from module_error_handler_plugin::common
                        ---
                        // Use safeError (guaranteed non-null) instead of raw error.
                        // Wrap in try/catch because some errorType objects are
                        // Java internals that DataWeave cannot introspect.
                        try
                            getErrorTypeAsString(vars.safeError.errorType)
                        catch(e)
                            "MULE:UNKNOWN"

ee:message.ee:set-payload:
%dw 2.0
                            import * from module_error_handler_plugin::common
                            output application/json

                            // safeError is guaranteed non-null from Step 1.
                            var errorEntry = getError(vars.errorType, vars.defaultErrors, vars.customErrors default {})
                            var responseKey = vars.responseKey
                            var responseError = errorEntry update {
                                    // Use the previous error message if it exists,
                                    // otherwise use the provided message.
                                    case message at .message -> if (!isEmpty(vars.previousError)) vars.previousError else message
                                }
                            ---
                            if (!isEmpty(responseKey) and (responseKey is String))
                                {
                                    (responseKey): responseError
                                }
                            else
                                responseError

ee:message.ee:set-attributes:
%dw 2.0
                            import * from module_error_handler_plugin::common
                            output application/java

                            // safeError.description is guaranteed non-null from Step 1.
                            var errorEntry    = getError(vars.errorType, vars.defaultErrors, vars.customErrors default {})
                            var code          = errorEntry.code default 500
                            var message       = toString(errorEntry.message, "Internal Server Error")
                            var previousMsg   = toString(vars.previousError)

                            // Extra defensive: safeError.description could still fail
                            // if the underlying object is a corrupted Java exception.
                            var description   = try toString(vars.safeError.description) catch(e) ""

                            // Concatenate current error message, previous error message,
                            // and error description without duplicates or empties.
                            var log = (([message, previousMsg, description] filter !isEmpty($)) distinctBy $) joinBy " | "
                            ---
                            {
                                httpStatus: code as Number,
                                errorLog: log
                            }

ee:message.ee:set-payload:
%dw 2.0
                                    output application/json
                                    var key = vars.responseKey default "error"
                                    var safeResponse = {
                                        code: 500,
                                        reason: "Internal Server Error",
                                        message: "An unexpected error occurred while processing the error response"
                                    }
                                    ---
                                    if (!isEmpty(key) and (key is String))
                                        { (key): safeResponse }
                                    else
                                        safeResponse
